<?php $content = \Passport\Copy::FAQ; ?>
<article class="info-page faq-page"><header class="info-heading"><p class="eyebrow"><?= $e($t('faqEyebrow')) ?></p><h1><?= $e($t('faqTitle')) ?></h1><p class="faq-subtitle"><?= $e($content['title']) ?></p><p class="lead"><?= $e($content['intro']) ?></p></header>
<div class="faq-layout"><nav class="faq-toc" aria-label="<?= $e($t('guideNavigation')) ?>"><?php foreach ($content['sections'] as $id => $section): ?><a href="#<?= $e($id) ?>"><?= $e($section['title']) ?> <span aria-hidden="true">↓</span></a><?php endforeach ?></nav>
<div><?php foreach ($content['sections'] as $id => $section): ?><section class="faq-section" id="<?= $e($id) ?>" aria-labelledby="heading-<?= $e($id) ?>"><h2 id="heading-<?= $e($id) ?>"><?= $e($section['title']) ?></h2><p class="muted"><?= $e($section['intro']) ?></p><div class="faq-questions"><?php foreach ($section['items'] as $i => $item): ?><details class="faq-item" <?= $i === 0 ? 'open' : '' ?>><summary><?= $e($item['q']) ?></summary><div class="faq-answer"><p><?= $e($item['a']) ?></p><?php if (isset($item['steps'])): ?><ol><?php foreach ($item['steps'] as $step): ?><li><?= $e($step) ?></li><?php endforeach ?></ol><?php endif ?><?php if (isset($item['link'])): ?><a href="<?= $e($item['link']['href']) ?>"><?= $e($item['link']['label']) ?> ↗</a><?php endif ?></div></details><?php endforeach ?></div></section><?php endforeach ?></div></div>
</article>
